namespace ghidra.app.plugin.core.function;

using ghidra.app.cmd.function;
using ghidra.app.services;
using ghidra.app.util.importer;
using ghidra.framework.cmd;
using ghidra.program.model.address;
using ghidra.program.model.lang;
using ghidra.program.model.listing;
using ghidra.util.task;

public class X86FunctionPurgeAnalyzer : AbstractAnalyzer {
	private static readonly string NAME = "X86 Function Callee Purge";
	private static readonly string DESCRIPTION =
		"Figures out the function Purge value for Callee cleaned up function call parameters (stdcall) on X86 platforms.";

	public X86FunctionPurgeAnalyzer() : base(NAME, DESCRIPTION, AnalyzerType.FUNCTION_ANALYZER)
    {
		setPriority(AnalysisPriority.FUNCTION_ANALYSIS);
		setDefaultEnablement(true);
	}

	/* @Override */
	public bool added(Program program, AddressSetView set, TaskMonitor monitor, MessageLog log) {
		BackgroundCommand<Program> cmd;

		cmd = new FunctionPurgeAnalysisCmd(set);

		cmd.applyTo(program, monitor);
		return true;
	}

	/* @Override */
	public bool canAnalyze(Program program) {
		// Only analyze 32-bit or less X86 programs
		Processor processor = program.getLanguage().getProcessor();
		if (program.getLanguage().getDefaultSpace().getSize() > 32) {
			return false;
		}
		return processor.equals(Processor.findOrPossiblyCreateProcessor("x86"));
	}

}
